var consent=consent||{};consent.cookies=(function(){'use_strict';function fadeIn(el){el.style.opacity='0';el.style.display='block';var last=+new Date();var tick=function(){el.style.opacity=+el.style.opacity+(new Date()-last)/200;last=+new Date();if(+el.style.opacity<1){(window.requestAnimationFrame&&requestAnimationFrame(tick))||setTimeout(tick,16);}};tick();}function fadeOut(el){el.style.opacity='1';var last=+new Date();var tick=function(){el.style.opacity=+el.style.opacity-(new Date()-last)/200;last=+new Date();if(+el.style.opacity>0){(window.requestAnimationFrame&&requestAnimationFrame(tick))||setTimeout(tick,16);}else{el.style.display='none';}};tick();}document.addEventListener('DOMContentLoaded',function(){if(getCookie('CookieConsent')===null){var el=document.querySelector('.cookie-consent');if(el){fadeIn(el);}}},false);function setCookie(key,value,days){var expires=new Date();expires.setTime(expires.getTime()+(days*24*60*60*1000));document.cookie=key+'='+value+';expires='+expires.toUTCString();}function getCookie(key){var keyValue=document.cookie.match('(^|;) ?'+key+'=([^;]*)(;|$)');return keyValue?keyValue[2]:null;}return{setCookieConsent:function(){setCookie('CookieConsent',true,360);var el=document.querySelector('.cookie-consent');if(el){fadeOut(el);}}};}());
